@implementation TFAIPersonaManagement
- (void)viewDidLoad{[super viewDidLoad];self.title=@"配置管理";self.view.tintColor=PersonaAccent();self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=72;}
