- (void)reload{NSString *query=self.query?:@"";self.items=TFAIPersonasSorted([TFAIPersonaStore.shared.personas filteredArrayUsingPredicate:[NSPredicate predicateWithBlock:^BOOL(TFAIPersona *p,NSDictionary *bindings){return !query.length||[p.name localizedCaseInsensitiveContainsString:query]||[p.summary localizedCaseInsensitiveContainsString:query];}]]);[self.tableView reloadData];}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)table{return 2;}
- (NSInteger)tableView:(UITableView *)table numberOfRowsInSection:(NSInteger)section{return section==0?1:MAX(1,self.items.count);}
- (CGFloat)tableView:(UITableView *)table heightForHeaderInSection:(NSInteger)section{return section==0?5:52;}
