- (NSString *)tableView:(UITableView *)table titleForFooterInSection:(NSInteger)section{return section==0?TFAIPersonaStore.shared.loadError.localizedDescription:@"自动模式会标记当前全局模型的推荐项；项目覆盖模型在实际发送时重新匹配。点右侧圆形按钮可切换为手动选择。";}
- (CGFloat)tableView:(UITableView *)table heightForFooterInSection:(NSInteger)section{return section==0?(TFAIPersonaStore.shared.loadError?UITableViewAutomaticDimension:3):UITableViewAutomaticDimension;}
