- (void)tableView:(UITableView *)table didSelectRowAtIndexPath:(NSIndexPath *)path{[table deselectRowAtIndexPath:path animated:YES];if(path.section==1&&path.row<self.items.count)[self edit:self.items[path.row]];}
- (void)preview{[self.navigationController pushViewController:[TFAIPersonaPreview new] animated:YES];}
- (void)manage{[self.navigationController pushViewController:[[TFAIPersonaManagement alloc]initWithStyle:UITableViewStyleInsetGrouped] animated:YES];}
- (void)add{[self edit:nil];}
