- (UISwipeActionsConfiguration *)tableView:(UITableView *)tableView leadingSwipeActionsConfigurationForRowAtIndexPath:(NSIndexPath *)path{if(path.section!=1||path.row>=self.items.count||!self.items[path.row].isBuiltin)return nil;TFAIPersona *p=self.items[path.row];UIContextualAction *reset=[UIContextualAction contextualActionWithStyle:UIContextualActionStyleNormal title:@"恢复原文" handler:^(UIContextualAction *action,UIView *view,void(^done)(BOOL)){done(YES);UIAlertController *alert=[UIAlertController alertControllerWithTitle:@"恢复内置原文？" message:@"本项正文、方式、描述和标记将恢复默认。" preferredStyle:UIAlertControllerStyleAlert];[alert addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[alert addAction:[UIAlertAction actionWithTitle:@"恢复" style:UIAlertActionStyleDestructive handler:^(UIAlertAction *a){NSError *e=nil;if(![TFAIPersonaStore.shared resetBuiltin:p.identifier error:&e])AIAlert(self,@"恢复失败",e.localizedDescription);[self reload];}]];[self presentViewController:alert animated:YES completion:nil];}];UISwipeActionsConfiguration *config=[UISwipeActionsConfiguration configurationWithActions:@[reset]];config.performsFirstActionWithFullSwipe=NO;return config;}
